function labActor(x,y,scale=1,c='#156f75',pose=0){return `<g transform="translate(${x} ${y}) scale(${scale})"><ellipse cx="0" cy="4" rx="22" ry="5" fill="#20344725"/><circle cx="0" cy="-65" r="12" fill="#f0c49c" stroke="#203447"/><rect x="-15" y="-51" width="30" height="32" rx="4" fill="${c}"/><path d="M-8 -19 L${-13+pose*5} 0 M8 -19 L${13-pose*5} 0" stroke="#203447" stroke-width="6"/><path d="M-15 -43 L-27 -23 M15 -43 L30 ${-29-pose*10}" stroke="${c}" stroke-width="6"/><path d="M30 ${-29-pose*10} L${40+pose*10} -67" stroke="#b76821" stroke-width="4"/></g>`;}
function slider(id,label,min,max,value,step=1){return `<label class="lab-control" for="${id}"><span>${esc(label)}</span><input id="${id}" type="range" min="${min}" max="${max}" value="${value}" step="${step}"><span id="${id}Value" class="lab-number"></span></label>`;}
function check(id,label,yes=false){return `<label class="lab-check"><input id="${id}" type="checkbox" ${yes?'checked':''}>${esc(label)}</label>`;}
function astarModel(cols,rows,walls,start,goal){
 const key=(x,y)=>y*cols+x;const s=key(...start),g=key(...goal);if(walls.has(s)||walls.has(g))return {path:[],expanded:0};
 const h=k=>Math.abs(k%cols-goal[0])+Math.abs(Math.floor(k/cols)-goal[1]);
 const open=[s], gs=new Map([[s,0]]), prev=new Map(),closed=new Set();
 while(open.length){open.sort((a,b)=>(gs.get(a)+h(a))-(gs.get(b)+h(b))||h(a)-h(b)||a-b);const u=open.shift();if(closed.has(u))continue;closed.add(u);
  if(u===g){const p=[u];while(prev.has(p.at(-1)))p.push(prev.get(p.at(-1)));return {path:p.reverse(),expanded:closed.size};}
  const x=u%cols,y=Math.floor(u/cols);for(const [dx,dy] of [[1,0],[0,1],[-1,0],[0,-1]]){const nx=x+dx,ny=y+dy;if(nx<0||ny<0||nx>=cols||ny>=rows)continue;const v=key(nx,ny);if(walls.has(v)||closed.has(v))continue;const ng=gs.get(u)+1;if(ng<(gs.get(v)??Infinity)){gs.set(v,ng);prev.set(v,u);if(!open.includes(v))open.push(v);}}
 }
 return {path:[],expanded:closed.size};
}
function topologicalModel(n,edges){const degree=Array(n).fill(0),out=Array.from({length:n},()=>[]);for(const [a,b]of edges){degree[b]++;out[a].push(b);}const q=[];degree.forEach((x,i)=>{if(x===0)q.push(i)});const r=[];while(q.length){const a=q.shift();r.push(a);for(const b of out[a])if(--degree[b]===0)q.push(b);}return r.length===n?r:null;}
