const TERMS=JSON.parse(document.getElementById('termData').textContent);
const termById=new Map(TERMS.map(t=>[t.id,t]));
const SOURCES=JSON.parse(document.getElementById('sourceData').textContent);
const VISUALS=JSON.parse(document.getElementById('visualData').textContent);
const LESSON_TERMS=JSON.parse(document.getElementById('lessonTermData').textContent);
