const ALIAS_PRIORITY=JSON.parse(document.getElementById('aliasPriorityData').textContent);
const reEscape=s=>s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
const aliasRegex=new RegExp(Object.keys(ALIASES).sort((a,b)=>b.length-a.length).map(reEscape).join('|'),'gi');
const asciiWord=c=>!!c&&/[A-Za-z0-9_]/.test(c);
let techOrigin=null, lastRoute='',currentTerm=null,lessonViews=new Map(),glossaryFilter={q:'',group:'all',models:false};
function pickTerm(alias,context){
 const a=alias.toLowerCase(),v=ALIASES[a];const n=typeof context==='number'?context:0;
 if(n>=161){if(a==='스킬')return [162].includes(n)?'skill-agent':'skill-tree';if(a==='노드')return [213,214].includes(n)?'skill-tree':'quest-graph';if(a==='anchor')return 'quest-marker';if(['커밋','commit'].includes(a))return 'transaction';}
 
 if(['binding','바인딩','anchor'].includes(a))return n>=105&&![132,151].includes(n)||context==='binding'?'binding':a==='anchor'?'canvas':'input-system';
 if(a==='local')return [1,2,3].includes(n)||n>=105?'tool':'local-world';
 if(['커밋','commit'].includes(a))return [138,139,140,141,152].includes(n)||context==='transaction'?'transaction':'git';
 if(a==='노드')return n===70||context==='shader-graph'?'shader-graph':[41,42,43,122,142].includes(n)||context==='skill-tree'?'skill-tree':'dependency';
 if(a==='스킬'&&n>=105)return 'skill-agent';
 return ALIAS_PRIORITY[a]||v[0];
}
function findTerms(text,context){
 const out=[],protectedSpans=[...text.matchAll(/https?:\/\/[^\s<>]+|[A-Za-z]:\\[^\s<>]+|(?:Assets|Docs|Packages|ProjectSettings|Library|harness|expansion2d|AI_REFERENCE)[/\\][^\s<>]+/g)].map(m=>[m.index,m.index+m[0].length]);
 aliasRegex.lastIndex=0;let m;while((m=aliasRegex.exec(text))!==null){const a=m.index,b=a+m[0].length,w=m[0];if(w==='메시'&&text[b]==='지')continue;if(w.length===1&&/[가-힣]/.test(text[a-1]||''))continue;if(asciiWord(w[0])&&asciiWord(text[a-1]))continue;if(asciiWord(w.at(-1))&&asciiWord(text[b]))continue;if(protectedSpans.some(([x,y])=>a<y&&b>x))continue;out.push({a,b,id:pickTerm(w,context),word:w});}return out;
}
function attachTermLinks(root,context,excludeId=null){
 const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT,{acceptNode(node){if(!node.nodeValue.trim()||!node.parentElement)return NodeFilter.FILTER_REJECT;return node.parentElement.closest('a,button,script,style,textarea,input,select,option,svg,.req-label,.req-num,.requirement-index,.term-chips,.source-list,.tech-sources,.tech-alias-list,.lab-controls,.lab-visual,.lab-output,.tech-jumpbar,.used-lessons')?NodeFilter.FILTER_REJECT:NodeFilter.FILTER_ACCEPT;}});
 const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);
 for(const node of nodes){const text=node.nodeValue,seen=new Set(),matches=findTerms(text,context).filter(m=>{if(m.id===excludeId||seen.has(m.id))return false;seen.add(m.id);return true;}).slice(0,node.parentElement.closest('.prompt-text')?35:18);if(!matches.length)continue;let p=0;const frag=document.createDocumentFragment();for(const m of matches){frag.append(document.createTextNode(text.slice(p,m.a)));const a=document.createElement('a');a.href='#tech-'+m.id;a.className='term-link';a.dataset.tech=m.id;a.textContent=m.word;a.setAttribute('aria-label',m.word+' 설명 열기');a.title=termById.get(m.id).lead;a.dataset.originToken=m.word;frag.append(a);p=m.b;}frag.append(document.createTextNode(text.slice(p)));node.replaceWith(frag);}
}
function chip(id){const t=termById.get(id);return `<a href="#tech-${id}" data-tech="${id}">${esc(t.title)}</a>`;}
function termRibbon(id){const v=LESSON_TERMS[id];return `<aside class="tech-ribbon" aria-label="이 페이지의 기술 해설"><strong>낯선 용어가 있나요?</strong><p class="term-hint">본문의 점선 밑줄을 누르면 그림이 있는 해설이 열립니다. <strong>읽던 단계로 돌아오기</strong>로 이 자리에서 이어갈 수 있어요.</p><div class="term-chips">${v.featured.slice(0,6).map(chip).join('')}</div><details class="all-terms"><summary>이 페이지에 나온 용어 ${v.all.length}개 모두 보기</summary><div class="term-chips">${v.all.map(chip).join('')}</div></details><p class="term-hint"><a href="#glossary" data-open-glossary>전체 기술 해설에서 찾기 →</a> · 메시지 복사는 설명 링크 없이 원문만 복사합니다.</p></aside>`;}
const originalShowLesson=showLesson;
