const originalHome=home;
home=function(){cleanLabs();currentTerm=null;originalHome();const h=$('.hero');if(h){h.insertAdjacentHTML('afterend',`<section class="card"><div class="tech-kicker">모르는 말에서 멈추지 않도록</div><h2>실습 옆에 기술 해설을 두었습니다</h2><p>프리팹·PPU·콜라이더·A*·훅처럼 낯선 단어를 누르면 쉬운 설명과 그림을 볼 수 있어요. 같은 용어는 같은 해설로 연결되고, 읽고 나면 원래 단계로 돌아옵니다.</p><div class="tech-begin-path">${['gameobject','component','prefab','ppu','collider','harness'].map(chip).join('')}</div><a class="bigButton" href="#glossary">${TERMS.length}개 기술 해설 전체 보기 →</a><p class="smalltext">모든 해설에는 그림·RPG 예시·흔한 오해·확인 질문이 있습니다. 값을 바꿔 보는 ${Object.keys(LAB_INFO).length}종의 설명 모형은 실제 Unity를 실행하지 않습니다.</p></section>`);}lastRoute='#home';};
