function wireTechNavigation(){document.querySelectorAll('[data-back-to-reading]').forEach(b=>b.onclick=goTechBack);document.querySelectorAll('[data-to-glossary]').forEach(b=>b.onclick=()=>{location.hash='glossary';});document.querySelectorAll('[data-start-reading]').forEach(b=>b.onclick=()=>{techOrigin=null;go(0);});}
