function glossaryHome(){
 cleanLabs();currentTerm=null;activeId=0;$('#breadcrumb').textContent='기술 해설 · 모르는 용어를 그림으로 이해하기';$('#content').innerHTML=`<div class="glossary-home">${backBar()}<header class="tech-hero"><div class="tech-kicker">그림과 작은 실험으로 이해하는 개발 용어</div><h1>모르는 용어가 나왔다면,<br>여기서 이해하고 이어가세요</h1><p class="glossary-intro">${TERMS.length}개 해설 장을 따로 모았습니다. 짧은 뜻풀이에서 끝내지 않고 <strong>무엇인지 → 어떻게 움직이는지 → 우리 RPG에서 어디에 쓰는지 → 무엇을 혼동하면 안 되는지</strong> 순서로 설명합니다.</p></header><section class="card"><h2>가장 기초부터 연결해서 읽기</h2><div class="tech-begin-path">${['unity','gameobject','component','transform','sprite','collider','prefab'].map((id,i)=>chip(id)+(i<6?'<span aria-hidden="true">→</span>':'')).join('')}</div><p class="smalltext">전부 외운 뒤 시작할 필요는 없습니다. 지금 실습에서 나온 말만 읽고 돌아가세요. 공식 문서는 선택 참고이며, 핵심 설명과 그림은 이 파일 안에 들어 있습니다.</p><div class="glossary-controls"><label>모르는 용어 찾기<input id="techSearch" placeholder="예: 피벗, Rigidbody2D, A*, 토큰" type="search" value="${esc(glossaryFilter.q)}"></label><label>분야<select id="techCategory"><option value="all">전체 분야</option>${[...new Set(TERMS.map(t=>t.group))].map(g=>`<option value="${esc(g)}">${esc(g)}</option>`).join('')}</select></label></div><label class="lab-check"><input id="modelsOnly" type="checkbox" ${glossaryFilter.models?'checked':''}>값을 바꾸는 모형이 있는 해설만 보기</label><div class="glossary-count glossary-count-live" id="techCount" aria-live="polite"></div></section><div id="techCards"></div></div>`;
 $('#techCategory').value=glossaryFilter.group;const f=()=>{glossaryFilter={q:$('#techSearch').value,group:$('#techCategory').value,models:$('#modelsOnly').checked};renderTechCards();};$('#techSearch').oninput=f;$('#techCategory').onchange=f;$('#modelsOnly').onchange=f;renderTechCards();wireTechNavigation();nav();lastRoute='#glossary';window.scrollTo({top:0,behavior:'instant'});
}
function renderTechCards(){const q=normalizeQuery(glossaryFilter.q);const found=TERMS.filter(t=>(glossaryFilter.group==='all'||t.group===glossaryFilter.group)&&(!glossaryFilter.models||t.lab)&&(!q||normalizeQuery([t.title,...t.aliases,t.lead,t.example].join(' ')).includes(q)));$('#techCount').textContent=`${found.length} / ${TERMS.length}개 해설 · 한국어와 영문 이름 모두 검색됩니다.`;let g='',h='';for(const t of found){if(t.group!==g){if(g)h+='</div>';g=t.group;h+=`<h2 class="tech-group-head">${esc(g)}</h2><div class="tech-cards">`;}h+=`<a class="tech-card" href="#tech-${t.id}" data-tech="${t.id}"><span class="category">TECH ${String(t.number).padStart(3,'0')}</span><h3>${esc(t.title)}</h3><p>${esc(t.lead)}</p>${t.lab?'<span class="model-badge">조작 모형 포함</span>':''}</a>`;}if(g)h+='</div>';$('#techCards').innerHTML=h||'<div class="tech-empty"><h2>일치하는 용어를 찾지 못했어요</h2><p>약어 또는 짧은 기본 단어로 다시 검색해 보세요. 예: “Collider2D” 대신 “충돌”, “AssetBundle” 대신 “번들”. 프로젝트의 임의 파일명·고유 ID는 별도 용어가 아닐 수 있습니다.</p></div>';}
function showTerm(id){
 cleanLabs();const t=termById.get(id);if(!t){glossaryHome();$('#techSearch').value=id;glossaryFilter.q=id;renderTechCards();return;}activeId=0;currentTerm=id;$('#breadcrumb').textContent='기술 해설 / '+t.title;
 const deep=t.deep?`<section class="tech-section section-anchor" id="techDeep"><h2>${esc(t.deep.title)}</h2>${t.deep.paragraphs.map(p=>`<p>${esc(p)}</p>`).join('')}<div class="tech-detail-table"><table><thead><tr>${t.deep.headers.map(h=>`<th scope="col">${esc(h)}</th>`).join('')}</tr></thead><tbody>${t.deep.rows.map(r=>`<tr>${r.map(c=>`<td>${esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section>`:'';
 const used=t.usedIn||[];const usedHTML=used.length?`<div class="used-lessons">${used.slice(0,8).map(n=>`<a href="#lesson-${String(n).padStart(3,'0')}" data-used-lesson="${n}">${String(n).padStart(2,'0')} · ${esc(byId.get(n).title)}</a>`).join('')}</div>${used.length>8?`<details><summary>사용된 페이지 ${used.length}개 모두 보기</summary><div class="used-lessons">${used.slice(8).map(n=>`<a href="#lesson-${String(n).padStart(3,'0')}" data-used-lesson="${n}">${String(n).padStart(2,'0')} · ${esc(byId.get(n).title)}</a>`).join('')}</div></details>`:''}`:'<p>이 용어는 다른 해설을 이해하기 위한 보충 개념입니다. 관련 개념에서 이어서 읽을 수 있습니다.</p>';
 $('#content').innerHTML=`<article class="tech-article">${backBar()}<header class="tech-hero"><div class="tech-kicker">TECH ${String(t.number).padStart(3,'0')} · ${esc(t.group)}</div><h1>${esc(t.title)}</h1><p class="tech-lead">${esc(t.lead)}</p><div class="tech-alias-list"><details><summary>같은 설명으로 찾아오는 이름 ${t.aliases.length}개</summary><p>${t.aliases.map(esc).join(' · ')}</p></details></div></header><nav class="tech-jumpbar" aria-label="이 해설 안에서 이동"><a href="#" data-section="techFigure">그림</a><a href="#" data-section="techHow">작동 원리</a>${t.lab?'<a href="#" data-section="techLab">조작해 보기</a>':''}<a href="#" data-section="techExample">게임 속 예</a><a href="#" data-section="techQuiz">확인 질문</a></nav><section class="tech-analogy"><h2>익숙한 것에 비유하면</h2><p>${esc(t.analogy)}</p></section><figure class="tech-figure section-anchor" id="techFigure"><img src="${VISUALS[id]}" alt="${esc(t.visualAlt)}" width="900" height="540"><div class="figure-actions"><span>아래 본문에서 그림의 각 단계를 자세히 풉니다.</span><button id="enlargeFigure">그림 크게 보기</button></div><figcaption>${esc(t.visualCaption)}</figcaption></figure><section class="tech-section section-anchor" id="techHow"><h2>이렇게 작동합니다</h2><div class="tech-process">${t.steps.map((s,i)=>`<article><span class="step-num">${i+1}</span><div><h3>${esc(s.label)}</h3><p>${esc(s.text)}</p></div></article>`).join('')}</div></section>${deep}${labHTML(t)}<section class="card tech-example section-anchor" id="techExample"><h2>우리 RPG에서는 이렇게 만나요</h2><p>${esc(t.example)}</p></section><section class="tech-mistake"><h2>이것과 혼동하지 마세요</h2><p>${esc(t.pitfall)}</p></section><section class="tech-quiz section-anchor" id="techQuiz"><h2>이해했는지 한 번 생각해 보기</h2><p class="question">${esc(t.question)}</p><details><summary>답과 이유 펼쳐 보기</summary><p>${esc(t.answer)}</p></details><p class="smalltext">답을 펼쳐도 실습 확인 체크나 게임 검사 상태는 바뀌지 않습니다.</p></section><section class="card"><h2>내 프로젝트에서 확인하고 싶다면</h2><p>원리를 읽은 뒤 실제 사용 대상을 AI에게 보여 달라고 요청할 수 있습니다. 설정을 직접 고치거나 명령을 입력할 필요는 없습니다.</p>${promptHTML(t.prompt,'tech-inspect')}</section><section class="tech-section"><h2>이어지는 개념</h2><p class="smalltext">여기에서도 모르는 용어가 나오면 연결된 설명을 읽으세요. 원래 실습으로 돌아가는 위치는 유지됩니다.</p><div class="term-chips">${t.related.map(chip).join('')}</div></section><section class="tech-section"><h2>이 개념을 사용하는 실습</h2>${usedHTML}</section><section class="tech-sources"><h2>참고와 설명의 범위</h2><p>${esc(t.sourceNote)}</p>${t.sources.length?`<ul>${t.sources.map(key=>`<li><a href="${esc(SOURCES[key].url)}" target="_blank" rel="noopener noreferrer">${esc(SOURCES[key].title)}</a></li>`).join('')}</ul>`:''}<p>그림·계산 예제·조작 모형은 자체 제작했습니다. 실제 Editor 스크린샷, 서비스 생성 결과, 성능 측정 또는 게임 테스트 결과가 아닙니다. 자료 확인: 2026년 9월 26일.</p></section>${backBar()}</article>`;
 attachPrompts({'tech-inspect':t.prompt});attachTermLinks($('#content'),id,id);wireTechNavigation();$('#enlargeFigure').onclick=()=>enlargeFigure(t);document.querySelectorAll('[data-section]').forEach(a=>a.onclick=e=>{e.preventDefault();document.getElementById(a.dataset.section)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});});initLab(t);nav();lastRoute='#tech-'+id;window.scrollTo({top:0,behavior:'instant'});
}
function enlargeFigure(t){const dialog=$('#imageDialog');$('#zoomTitle').textContent=t.title;$('#zoomImage').src=VISUALS[t.id];$('#zoomImage').alt=t.visualAlt;$('#zoomContainer').classList.remove('fit');$('#fitZoom').textContent='화면에 맞추기';$('#zoomDescription').textContent=t.visualCaption;if(dialog.showModal)dialog.showModal();else dialog.setAttribute('open','');}
$('#closeImageDialog').onclick=()=>$('#imageDialog').close();$('#fitZoom').onclick=()=>{const c=$('#zoomContainer');c.classList.toggle('fit');$('#fitZoom').textContent=c.classList.contains('fit')?'원래 크기로 보기':'화면에 맞추기';};
document.addEventListener('click',e=>{const a=e.target.closest('a[data-tech],a[data-open-glossary]');if(a){rememberOrigin();closeNav();}const used=e.target.closest('[data-used-lesson]');if(used){const n=Number(used.dataset.usedLesson);if(!techOrigin||techOrigin.id!==n)lessonViews.delete(n);closeNav();}},true);
$('#openGlossary').onclick=()=>{rememberOrigin();closeNav();location.hash='glossary';};$('#navGlossary').onclick=()=>{rememberOrigin();closeNav();location.hash='glossary';};
render=function(){
 const h=location.hash;const tech=h.match(/^#tech-([a-z0-9-]+)$/);if(tech){showTerm(tech[1]);return;}
 if(h==='#glossary'){glossaryHome();return;}
 const m=h.match(/^#lesson-(\d{1,3})$/);if(m&&byId.has(Number(m[1]))){const id=Number(m[1]),fromTech=lastRoute.startsWith('#tech-')||lastRoute==='#glossary';const pos=fromTech?lessonViews.get(id):null;showLesson(id,pos?.step??null,!pos);if(pos)requestAnimationFrame(()=>window.scrollTo({top:pos.scroll,behavior:'instant'}));}
 else{home();window.scrollTo({top:0,behavior:'instant'});if(h==='#routes')setTimeout(()=>$('#routes')?.scrollIntoView(),0);}
};
