const REVISED_LESSONS = new Set([27,88,94,121,125,129,130,136,141,185,192,240]);
const BOOTSTRAP_HTML=`<section class="card bootstrap-card" id="localStart"><span class="eyebrow">처음 한 번 · 개발 명령 입력 없음</span><h2>AI 작업창이 아직 없다면 여기서 시작하세요</h2><p>지금 읽는 웹페이지는 내 PC를 조작하지 않습니다. 처음 AI 앱 설치·로그인·권한 선택은 직접 하고, 그 뒤의 게임 파일·설정·명령은 AI가 수행합니다.</p><ol class="bootstrap-steps"><li><strong>공식 데스크톱 앱을 설치하고 로그인합니다.</strong> 아래 공식 다운로드 페이지에서 Windows 설치 프로그램을 받습니다. Code 사용 권한이 없다는 안내가 나오면 계정·요금 조건을 확인하고 결제 여부를 직접 결정합니다. Windows의 로컬 Code에서 Git 설치를 요구하면 공식 Git 설치 프로그램으로 준비한 뒤 앱을 다시 엽니다.</li><li><strong>Chat이 아니라 Code 탭을 선택합니다.</strong> 실행 환경은 Windows의 <b>Local</b>을 고릅니다. Cloud·WSL은 지금 열 Unity Editor와 별개 환경일 수 있으므로 첫 연결에 섞지 않습니다.</li><li><strong>Select folder에서 작업할 폴더를 선택합니다.</strong> 기존 업무 프로젝트가 아닌 준비용 폴더를 지정합니다. 아직 게임 프로젝트가 없어도 됩니다. 새 Unity 프로젝트 생성은 다음 요청에서 AI가 맡습니다.</li><li><strong>모델과 권한을 확인합니다.</strong> 실제 계정에서 Opus 5.5 선택 가능 여부를 확인합니다. 권한은 우선 <b>Manual</b>로 두어 변경·실행 범위를 읽고 승인합니다. Plan은 조사·계획용이므로 실제 제작이 필요하면 실행 가능한 권한 모드로 바꿉니다. 없는 모델이나 권한을 우회하지 않습니다.</li><li><strong>아래의 첫 연결 확인 메시지를 보냅니다.</strong> AI가 읽은 전체 경로를 확인합니다. 별도 worktree를 열었다면 원본과 후보 경로를 구분하고, Unity가 열고 있는 프로젝트와 실제 대상이 같은지 확인하게 합니다. 로컬 파일을 읽을 수 없으면 아직 다음 단계로 가지 않습니다.</li></ol><div class="callout">화면이나 버튼 이름이 다르면 Code 탭·Local 환경·대상 폴더·권한의 네 가지를 먼저 찾으세요. 계정 제한은 도구가 없는 상태로 표시하고, 비밀번호나 인증 코드를 채팅에 전달하지 않습니다.</div><p class="smalltext"><a href="https://code.claude.com/docs/en/desktop-quickstart" target="_blank" rel="noopener noreferrer">공식 다운로드와 현재 설치 화면</a> · <a href="https://git-scm.com/download/win" target="_blank" rel="noopener noreferrer">Git for Windows 공식 설치</a> · <a href="https://code.claude.com/docs/en/desktop" target="_blank" rel="noopener noreferrer">현재 계정·권한·작업 환경 안내</a><br>절차 확인: 2026-09-26. 다운로드·로그인만 외부 앱에서 수행하며 설명을 다른 문서에서 먼저 공부할 필요는 없습니다.</p></section>`;
function workedCaseHTML(l){const c=l.learningCase;if(!c)return '';return `<section class="card worked-case" id="workedCase"><details ${activeStep===2?'open':''}><summary>구체적인 예로 이해하기 · ${esc(c.title)}</summary><div class="case-inner"><p class="case-idea">${esc(c.idea)}</p><div class="case-grid"><div><span class="case-kicker">시작 상태</span><p>${esc(c.before)}</p></div><div><span class="case-kicker">직접 해 볼 동작</span><p>${esc(c.action)}</p></div><div class="case-result"><span class="case-kicker">보여야 하는 결과</span><p>${esc(c.after)}</p></div></div><p class="case-trap"><b>이렇게 되면 아직 안 된 것입니다.</b> ${esc(c.trap)}</p><details class="understanding"><summary>잠깐 생각해 보기 · ${esc(c.question)}</summary><p>${esc(c.answer)}</p></details><p class="smalltext">설명용 예제입니다. 실제 결과는 AI가 준비한 현재 프로젝트에서 확인하며, 이 해설을 열어 보는 것으로 완료 기록이 바뀌지 않습니다.</p></div></details></section>`;}
function ruleCardHTML(l){return l.rulesHtml?`<section class="card rules-card" id="rulesCard"><details><summary>이 작업에서 사용할 값과 규칙 전체</summary><div class="rules-inner"><p class="smalltext">아래 값은 이 프로젝트의 시작 규격입니다. 성능·재미를 이미 측정한 결과가 아닙니다. 파일 작성은 AI가 수행합니다. 값을 바꾸려면 이유와 영향을 먼저 정한 뒤 같은 검사로 비교합니다.</p>${l.rulesHtml}</div></details></section>`:'';}
function transferHTML(l){const t=l.transfer;return t?`<section class="card transfer-card" id="transferCard"><span class="eyebrow">준비된 요구에서 한 걸음 더</span><h2>${esc(t.title)}</h2><p>${esc(t.task)}</p><div class="expected"><span class="tag">내가 설명할 수 있어야 하는 결과</span><p>${esc(t.acceptance)}</p></div><p>먼저 자신의 말로 <strong>목적·정상 결과·예외 상황·바꾸지 않을 것</strong>을 정하세요. 코드·설정·검사는 AI에게 맡기고, 실제로 보인 결과와 다르면 무엇이 달랐는지 알려 주세요.</p><p class="smalltext">별도의 정답 프롬프트를 복사하는 과제가 아닙니다. 완료 체크 수로 능력이나 출시 가능성을 판정하지 않습니다.</p></section>`:'';}
function diagnosisHTML(l){return `<section class="card diagnostic-card" id="diagnosticCard"><details><summary>계획만 받았거나 결과가 다를 때</summary><div class="case-inner"><div class="table-wrap"><table><thead><tr><th>지금 보인 상태</th><th>다음에 요청할 것</th></tr></thead><tbody><tr><td>계획만 있고 실제 파일·화면이 없음</td><td>권한 모드와 실행 가능한 로컬 도구를 확인한 뒤, 승인한 범위의 실제 작업을 수행하도록 요청합니다. 아래 ‘작은 결과부터’ 요청도 사용할 수 있습니다.</td></tr><tr><td>컴파일 오류 때문에 실행할 수 없음</td><td>첫 오류의 실제 파일과 로그를 읽고 하나를 고친 뒤 다시 컴파일하게 합니다. 마지막 화면 오류부터 추측하지 않습니다.</td></tr><tr><td>코드는 있지만 화면이 그대로임</td><td>지금 열린 프로젝트·씬·프리팹의 실제 컴포넌트와 참조를 추적하게 합니다. 예제 코드만 수정한 것은 아닌지 확인합니다.</td></tr><tr><td>오류는 없지만 행동이 다름</td><td>시작 상태→누른 순서→기대 결과→실제 결과를 자신의 말로 보냅니다. 같은 입력으로 재현하고 최소 수정한 뒤 다시 비교합니다.</td></tr><tr><td>기기·인증·비용 승인이 없음</td><td>차단된 범위와 가능한 범위를 나눕니다. 모델이나 테스트 조건을 몰래 바꿔 성공으로 만들지 않습니다.</td></tr></tbody></table></div><details class="small-slice-preview"><summary>AI에게 보낼 요청을 먼저 읽기</summary><p id="smallSliceText"></p></details><button id="copySmallSlice">작은 결과부터 만들기 요청 복사</button><p class="smalltext">이 요청은 현재 목표를 작은 실행 단계로 나눕니다. 원래 조건을 삭제하거나 후반 검사를 생략하라는 뜻은 아닙니다.</p></div></details></section>`;}
const showBeforeV13=showLesson;
showLesson=function(id,step=null,scroll=true){showBeforeV13(id,step,scroll);const l=byId.get(id);if(!l)return;
 const header=document.querySelector('.lesson-header'), navSteps=document.querySelector('.steps-nav'), figure=document.querySelector('[data-lesson-visual]');
 // Keep every original diagram, but don't force a full-screen diagram before every prompt.
 if(figure){const wrap=document.createElement('details');wrap.className='compact-figure';wrap.id='figureDetails';wrap.innerHTML='<summary>기능의 구조 그림 펼치기 <span>정상 흐름·실패 경계·확대</span></summary>';figure.before(wrap);wrap.append(figure);header.after(wrap);}
 const flow=LESSON_VISUALS[String(id)].flow;
 header.querySelector('.goal').insertAdjacentHTML('afterend',`<ol class="at-a-glance" aria-label="기능의 핵심 흐름">${flow.map((x,i)=>`<li><span>${i+1}</span>${esc(x)}</li>`).join('')}</ol>`);
 // Put explicit target and step selector ahead of large supporting material.
 const ribbon=document.querySelector('.tech-ribbon');
 if(ribbon){const terms=document.createElement('details');terms.className='compact-terms';terms.id='termListDetails';const count=LESSON_TERMS[id]?.all?.length||0;terms.innerHTML=`<summary>모르는 용어가 있나요? <span>이 페이지의 ${count}개 해설 · 본문의 점선 밑줄로도 열 수 있어요</span></summary>`;ribbon.before(terms);terms.append(ribbon);}
 navSteps.insertAdjacentHTML('beforebegin',`<nav class="learning-jumps" aria-label="현재 페이지에서 바로 보기"><button data-jump="stepPanel">현재 메시지</button><button data-jump="figureDetails">그림</button>${l.learningCase?'<button data-jump="workedCase">구체적인 예</button>':''}${l.rulesHtml?'<button data-jump="rulesCard">값·규칙</button>':''}<button data-jump="diagnosticCard">막힘 진단</button></nav>`);
 const panel=document.getElementById('stepPanel');panel.insertAdjacentHTML('afterend',workedCaseHTML(l)+ruleCardHTML(l)+diagnosisHTML(l)+transferHTML(l));
 if(id===1){panel.insertAdjacentHTML('beforebegin',`<div class="callout bootstrap-link"><strong>로컬 AI 작업창이 준비되지 않았다면</strong> 먼저 <button id="openLocalStart" class="small">화면으로 시작하는 준비 안내</button>를 여세요. 터미널 명령을 직접 입력하지 않습니다.</div>`);document.getElementById('openLocalStart').onclick=()=>{location.hash='home';setTimeout(()=>{const x=document.getElementById('localStart');x?.scrollIntoView({behavior:'instant'});},80);};}
 if(REVISED_LESSONS.has(id)&&rec(id).checked.some(Boolean)){panel.insertAdjacentHTML('afterbegin','<p class="revision-note">이 페이지의 조건은 개정13판에서 바로잡았습니다. 이전 확인 기록은 보존합니다. 체크가 있다는 이유로 수정된 조건을 이미 검증한 것은 아니므로 현재 요청과 실제 결과를 다시 비교하세요.</p>');}
 const mini=`현재 “${l.title}”의 전체 요구는 유지하되, 가장 작은 실행 가능한 결과부터 만들어 줘. 먼저 실제 파일과 연결 상태를 조사하고, 서로 의존하는 작업을 작은 단계로 나눠 줘. 계획 제시로 끝내지 말고 승인한 첫 단계의 코드·설정·실행·관련 검사를 직접 수행해 줘. 결과를 보여 준 뒤 남은 조건을 이어서 처리하고, 아직 하지 않은 검사를 통과했다고 적지 마. 원본과 이전 실패 기록을 보존해 줘.`;
 document.getElementById('smallSliceText').textContent=mini;
 document.getElementById('copySmallSlice').onclick=()=>copyText(mini);
 document.querySelectorAll('[data-jump]').forEach(b=>b.onclick=()=>{const target=document.getElementById(b.dataset.jump);if(!target)return;const details=target.matches('details')?target:(target.id==='stepPanel'?null:target.querySelector('details'));if(details)details.open=true;target.scrollIntoView({behavior:'instant',block:'start'});target.setAttribute('tabindex','-1');target.focus({preventScroll:true});});
 // Tab keyboard navigation, without changing learner checkboxes.
 const tabs=[...document.querySelectorAll('[data-step]')];tabs.forEach((b,i)=>{b.id='step-tab-'+i;b.tabIndex=i===activeStep?0:-1;b.addEventListener('keydown',e=>{let n;if(e.key==='ArrowRight')n=(i+1)%4;else if(e.key==='ArrowLeft')n=(i+3)%4;else if(e.key==='Home')n=0;else if(e.key==='End')n=3;else return;e.preventDefault();showLesson(id,n,false);document.getElementById('step-tab-'+n)?.focus();});});panel.setAttribute('aria-labelledby','step-tab-'+activeStep);
 for(const sel of ['#workedCase','#rulesCard','#transferCard','#diagnosticCard']){const el=document.querySelector(sel);if(el)attachTermLinks(el,id);}
 applyReadingTheme();
};
const homeBeforeV13=home;
home=function(){homeBeforeV13();const section=[...document.querySelectorAll('#content>.card')].find(x=>x.querySelector('h2')?.textContent==='시작 전에 딱 한 번');if(section)section.insertAdjacentHTML('beforebegin',BOOTSTRAP_HTML);
 const intro=[...document.querySelectorAll('#content>.card')].find(x=>x.textContent.includes('그림을 보고, 요청의 이유를 이해하며 진행하세요'));
 if(intro){intro.querySelector('h2').textContent='만들 결과를 먼저 보고, 필요한 설명을 펼쳐 읽으세요';intro.querySelector('.appearance-note').textContent='256개 실습 · 331개 기술 해설 · 전체 규격 표시 · 63개 구체적인 비교 예제. 현재 자료는 독립 비평가·Unity 실환경·초보 완주 심사 전의 검토 후보입니다.';}
 applyReadingTheme();};
window.AshfallReview={version:13,workedCases:LESSONS.filter(l=>l.learningCase).length,rulesPages:LESSONS.filter(l=>l.rulesHtml).length,independentReview:'BLOCKED',updatedLessons:[...REVISED_LESSONS]};

window.addEventListener('hashchange',render);
render();
window.AshfallPlaybook={version:13,lessonCount:LESSONS.length,termCount:TERMS.length,getRoute:()=>[...route()],getProgress:()=>JSON.parse(JSON.stringify(state)),validateProgress:validateState};
window.AshfallGlossary={version:13,nearestRank,mapXZ,findTerms,astarModel,topologicalModel,getOrigin:()=>techOrigin?{...techOrigin}:null,getCurrentTerm:()=>currentTerm,termIds:TERMS.map(t=>t.id)};
